{"implementation": "def solve(case):
    from fractions import Fraction

    if "segments" not in case or "budget" not in case:
        raise ValueError("Missing required top-level fields: segments, budget")

    segments = case["segments"]
    budget = case["budget"]

    for i, seg in enumerate(segments):
        for field in ("name", "importance", "minimum", "capacity"):
            if field not in seg:
                raise ValueError(f"Segment {i} missing required field '{field}'")

    n = len(segments)
    importances = [seg["importance"] for seg in segments]
    minimums    = [seg["minimum"]    for seg in segments]
    capacities  = [seg["capacity"]   for seg in segments]
    names       = [seg["name"]       for seg in segments]

    quota_sum    = sum(minimums)
    capacity_sum = sum(capacities)

    if budget < quota_sum:
        raise ValueError(
            f"Budget {budget} is below minimum quota sum {quota_sum}"
        )
    if budget > capacity_sum:
        raise ValueError(
            f"Budget {budget} exceeds total capacity {capacity_sum}"
        )

    allocations = list(minimums)
    remaining   = budget - quota_sum

    while remaining > 0:
        best_idx   = None
        best_score = None
        for i in range(n):
            if allocations[i] >= capacities[i]:
                continue
            # score = importance / (next position) = importance / (alloc + 1)
            # Use Fraction for exact rational comparison; no float rounding.
            score = Fraction(importances[i], allocations[i] + 1)
            # Strict-greater-than preserves original order on ties
            # (first encountered maximum index wins).
            if best_score is None or score > best_score:
                best_score = score
                best_idx   = i
        if best_idx is None:
            raise ValueError(
                "No available segment can absorb the remaining budget"
            )
        allocations[best_idx] += 1
        remaining -= 1

    by_name = {names[i]: allocations[i] for i in range(n)}
    total   = sum(allocations)

    return {
        "allocations": allocations,
        "by_name":     by_name,
        "total":       total,
    }
